-- Reuse immutable reviewed net revisions;do not create a second payroll ledger.
CREATE FUNCTION public.calculated_net_request_valid(i jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE keys text[]:=ARRAY['periodId','expectedPeriodVersion','pensionableEarnings','insurableEarnings','noQuebecTransfer','noOtherSameEmployerPayments','noNonCashOrZeroNetPayments','eligibilityReview','fullyTaxableCashRemuneration','noBonusesOrOtherTaxAdjustments'];k text;BEGIN
 IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i?&keys) OR i-keys<>'{}'::jsonb OR octet_length(i::text)>16384 OR jsonb_typeof(i->'periodId') IS DISTINCT FROM 'string' OR i->>'periodId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR jsonb_typeof(i->'expectedPeriodVersion') IS DISTINCT FROM 'number' OR i->>'expectedPeriodVersion'!~'^[1-9][0-9]{0,9}$' OR(i->>'expectedPeriodVersion')::bigint>2147483646 OR public.work_money_valid(i->'pensionableEarnings',2) IS NOT TRUE OR public.work_money_valid(i->'insurableEarnings',2) IS NOT TRUE OR jsonb_typeof(i->'eligibilityReview') IS DISTINCT FROM 'string' OR length(btrim(i->>'eligibilityReview')) NOT BETWEEN 1 AND 2000 OR i->>'eligibilityReview'~'[[:cntrl:]]' THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['noQuebecTransfer','noOtherSameEmployerPayments','noNonCashOrZeroNetPayments','fullyTaxableCashRemuneration','noBonusesOrOtherTaxAdjustments'] LOOP IF i->k IS DISTINCT FROM 'true'::jsonb THEN RETURN false;END IF;END LOOP;RETURN true;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;
CREATE FUNCTION public.calculated_net_source(p_run uuid,i jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE g public.payrun_groups%ROWTYPE;period record;tax record;s jsonb;history jsonb;n integer;BEGIN
 IF public.calculated_net_request_valid(i) IS NOT TRUE THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_REQUEST_INVALID');END IF;
 s=public.payrun_net_source(p_run);IF s IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO g FROM public.payrun_groups WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_run;
 SELECT h.id,h.version,h.profile_id,r.tax_profile_version,r.definition,t.person_id,t.employer_id,t.tax_year INTO period FROM public.payroll_tax_periods h JOIN public.payroll_tax_period_revisions r ON r.academy_id=h.academy_id AND r.period_id=h.id AND r.version=h.version JOIN public.payroll_tax_profiles t ON t.academy_id=h.academy_id AND t.id=h.profile_id WHERE h.academy_id=g.academy_id AND h.id=(i->>'periodId')::uuid;
 IF period.id IS NULL OR period.version<>(i->>'expectedPeriodVersion')::integer OR period.definition->'active' IS DISTINCT FROM 'true'::jsonb OR period.definition->>'regularRunId' IS DISTINCT FROM p_run::text OR period.person_id<>g.person_id OR period.tax_year<>2026 OR g.unit_scale<>2 OR(SELECT code FROM public.finance_currencies WHERE academy_id=g.academy_id AND id=g.currency_id) IS DISTINCT FROM 'CAD' OR jsonb_array_length(g.source_snapshot->'contexts')<>1 OR g.source_snapshot#>>'{contexts,0,employerId}' IS DISTINCT FROM period.employer_id::text OR g.source_snapshot#>>'{contexts,0,classification}' IS DISTINCT FROM 'employee' OR g.source_snapshot#>>'{contexts,0,countryCode}' IS DISTINCT FROM 'CA' THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_PERIOD_SOURCE_CHANGED');END IF;
 SELECT * INTO tax FROM public.payroll_tax_profile_revisions WHERE academy_id=g.academy_id AND profile_id=period.profile_id AND effective_on<=g.planned_pay_on ORDER BY effective_on DESC,version DESC LIMIT 1;
 IF tax.version IS DISTINCT FROM period.tax_profile_version OR tax.definition->'active' IS DISTINCT FROM 'true'::jsonb OR tax.definition->>'provinceOfEmployment' IS DISTINCT FROM 'ON' OR tax.definition#>>'{federalTd1,status}' IS DISTINCT FROM 'recorded' OR tax.definition#>>'{provincialDeclaration,status}' IS DISTINCT FROM 'recorded' OR tax.definition->>'incomeTaxExemption' IS DISTINCT FROM 'none' OR NOT(tax.definition?'ontarioTaxReductionClaimCount') OR tax.definition#>>'{pension,plan}' IS DISTINCT FROM 'CPP' OR tax.definition#>>'{pension,status}' IS DISTINCT FROM 'subject' OR tax.definition#>>'{ei,status}' IS DISTINCT FROM 'subject' OR tax.definition#>>'{ei,employerPlan}' IS DISTINCT FROM 'standard_1_4' THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_TAX_SOURCE_CHANGED');END IF;
 IF s->'cancellationId'<>'null'::jsonb OR s->'recordedSourcesCurrent' IS DISTINCT FROM 'true'::jsonb OR(i->>'pensionableEarnings')::numeric*100>g.gross_minor OR(i->>'insurableEarnings')::numeric*100>g.gross_minor OR EXISTS(SELECT 1 FROM jsonb_array_elements(g.source_snapshot->'items') x WHERE x->>'kind'='manual_bonus') THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_GROSS_SOURCE_CHANGED');END IF;
 -- IDs/versions reference immutable source rows;hash the bounded source list,
 -- not private forms,receipt contents or repeated large gross snapshots.
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb) INTO history FROM(
  SELECT pay.id,pay.amount_minor::text,pay.input->>'paidAt' paid_at,pay.reversal_id,p.id posting_id,p.reversal_id posting_reversal,h.profile_id,h.version,r.state,past.version past_tax_version
  FROM public.payrun_payments pay JOIN public.payrun_net_postings p ON p.academy_id=pay.academy_id AND p.id=pay.posting_id JOIN public.payrun_groups old ON old.academy_id=p.academy_id AND old.id=p.run_id
  LEFT JOIN public.paid_tax_records h ON h.academy_id=pay.academy_id AND h.payment_id=pay.id LEFT JOIN public.paid_tax_record_revisions r ON r.academy_id=h.academy_id AND r.payment_id=h.payment_id AND r.version=h.version
  LEFT JOIN LATERAL(SELECT version FROM public.payroll_tax_profile_revisions WHERE academy_id=g.academy_id AND profile_id=period.profile_id AND effective_on<=((pay.input->>'paidAt')::timestamptz AT TIME ZONE(period.definition->>'timeZone'))::date ORDER BY effective_on DESC,version DESC LIMIT 1)past ON true
  WHERE old.academy_id=g.academy_id AND old.id<>g.id AND old.person_id=g.person_id AND jsonb_array_length(old.source_snapshot->'contexts')=1 AND old.source_snapshot#>>'{contexts,0,employerId}'=period.employer_id::text AND old.source_snapshot#>>'{contexts,0,countryCode}'='CA' AND old.source_snapshot#>>'{contexts,0,classification}'='employee' AND((pay.input->>'paidAt')::timestamptz AT TIME ZONE(period.definition->>'timeZone'))::date BETWEEN DATE '2026-01-01' AND g.planned_pay_on ORDER BY pay.id LIMIT 501
 )x;n=jsonb_array_length(history);IF n>500 THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_HISTORY_REQUIRES_BACKGROUND_JOB');END IF;
 IF EXISTS(SELECT 1 FROM public.payrun_net_postings p JOIN public.payrun_groups old ON old.academy_id=p.academy_id AND old.id=p.run_id WHERE p.academy_id=g.academy_id AND old.id<>g.id AND old.person_id=g.person_id AND jsonb_array_length(old.source_snapshot->'contexts')=1 AND old.source_snapshot#>>'{contexts,0,employerId}'=period.employer_id::text AND old.source_snapshot#>>'{contexts,0,classification}'='employee' AND old.source_snapshot#>>'{contexts,0,countryCode}'='CA' AND old.planned_pay_on BETWEEN DATE '2026-01-01' AND g.planned_pay_on AND p.reversal_id IS NULL AND p.plan#>>'{net,amounts,netMinor}'='0' ) THEN RETURN jsonb_build_object('unavailable','CALCULATED_NET_ZERO_NET_HISTORY_REVIEW_REQUIRED');END IF;
 RETURN jsonb_build_object('request',i,'incomeTaxCalculationVersion','ca-on-2026-option1-regular-v1','contributionCalculationVersion','ca-2026-cpp-ei-salary-v1','periodId',period.id,'periodVersion',period.version,'periodSha256',encode(sha256(convert_to(period.definition::text,'UTF8')),'hex'),'taxProfileId',period.profile_id,'taxProfileVersion',tax.version,'taxSha256',encode(sha256(convert_to(tax.definition::text,'UTF8')),'hex'),'paidHistory',history,'paidHistorySha256',encode(sha256(convert_to(history::text,'UTF8')),'hex'),'paidHistoryCount',n,'unavailable',NULL);
END $$;
CREATE FUNCTION public.calculated_net_basis(p_run uuid,p_before integer,i jsonb) RETURNS jsonb LANGUAGE sql SET search_path=pg_catalog AS $$ SELECT public.payrun_net_basis(p_run,p_before)||jsonb_build_object('calculation',public.calculated_net_source(p_run,i)) $$;
CREATE FUNCTION public.calculated_net_current(p_run uuid,p_version integer) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c jsonb;BEGIN
 SELECT source_snapshot->'calculation' INTO c FROM public.payrun_net_revisions WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND run_id=p_run AND version=p_version;IF NOT FOUND THEN RETURN false;END IF;IF c IS NULL THEN RETURN true;END IF;
 RETURN public.calculated_net_source(p_run,c->'request') IS NOT DISTINCT FROM c;
END $$;
-- Preserve helper identities,ACLs and the existing human approval/audit/effect
-- requirements. Only the optional source-calculation branch is extended.
DO $$ DECLARE body text;needle text;replacement text;BEGIN
 SELECT pg_get_functiondef('public.guard_payrun_net_revision()'::regprocedure) INTO body;
 needle='b=public.payrun_net_basis(NEW.run_id,NEW.version-1);';replacement='b=CASE WHEN p.action=''work.payrun-net.calculate'' THEN public.calculated_net_basis(NEW.run_id,NEW.version-1,p.payload->''calculationRequest'')||jsonb_build_object(''generatedDefinition'',NEW.definition) ELSE public.payrun_net_basis(NEW.run_id,NEW.version-1) END;';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_GUARD_PATCH_CHANGED';END IF;body=replace(body,needle,replacement);
 needle='p.action IS DISTINCT FROM ''work.payrun-net.change''';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_ACTION_PATCH_CHANGED';END IF;body=replace(body,needle,'p.action NOT IN(''work.payrun-net.change'',''work.payrun-net.calculate'')');
 needle='OR p.payload IS DISTINCT FROM jsonb_build_object(''expectedVersion'',NEW.version-1,''state'',NEW.state,''definition'',NEW.definition,''reason'',NEW.reason)';replacement='OR(p.action=''work.payrun-net.calculate'' AND(NEW.state<>''prepared'' OR EXISTS(SELECT 1 FROM public.payrun_net_postings post JOIN public.payrun_payments pay ON pay.academy_id=post.academy_id AND pay.posting_id=post.id WHERE post.academy_id=NEW.academy_id AND post.run_id=NEW.run_id) OR b#>>''{calculation,unavailable}'' IS NOT NULL OR b->''calculation''=''null''::jsonb)) OR p.payload IS DISTINCT FROM(CASE WHEN p.action=''work.payrun-net.calculate'' THEN jsonb_build_object(''expectedVersion'',NEW.version-1,''calculationRequest'',p.payload->''calculationRequest'',''reason'',NEW.reason) ELSE jsonb_build_object(''expectedVersion'',NEW.version-1,''state'',NEW.state,''definition'',NEW.definition,''reason'',NEW.reason) END)';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_PAYLOAD_PATCH_CHANGED';END IF;EXECUTE replace(body,needle,replacement);
 SELECT pg_get_functiondef('public.payrun_net_complete()'::regprocedure) INTO body;needle='public.payrun_net_basis(NEW.run_id,NEW.version-1)';replacement='(CASE WHEN NEW.source_snapshot?''calculation'' THEN public.calculated_net_basis(NEW.run_id,NEW.version-1,(SELECT payload->''calculationRequest'' FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id))||jsonb_build_object(''generatedDefinition'',NEW.definition) ELSE public.payrun_net_basis(NEW.run_id,NEW.version-1) END)';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_COMPLETE_PATCH_CHANGED';END IF;body=replace(body,needle,replacement);needle='a.action=''work.payrun-net.change''';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_AUDIT_PATCH_CHANGED';END IF;EXECUTE replace(body,needle,'a.action=(SELECT action FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id)');
 SELECT pg_get_functiondef('public.payrun_net_effect_required()'::regprocedure) INTO body;needle='NEW.action=''work.payrun-net.change''';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_EFFECT_PATCH_CHANGED';END IF;EXECUTE replace(body,needle,'NEW.action IN(''work.payrun-net.change'',''work.payrun-net.calculate'')');
 SELECT pg_get_functiondef('public.payrun_posting_plan(uuid,jsonb)'::regprocedure) INTO body;needle=' scale=r.unit_scale;gross=r.gross_minor;';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_POSTING_PATCH_CHANGED';END IF;EXECUTE replace(body,needle,' IF public.calculated_net_current(p_run,n.version) IS NOT TRUE THEN RETURN jsonb_build_object(''unavailable'',''CALCULATED_NET_SOURCE_CHANGED'');END IF;'||needle);
 SELECT pg_get_functiondef('public.payrun_payment_plan(uuid,jsonb,uuid)'::regprocedure) INTO body;needle=' scale=(s->>''unitScale'')::integer;';IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NET_CALCULATION_PAYMENT_PATCH_CHANGED';END IF;EXECUTE replace(body,needle,' IF public.calculated_net_current(p.run_id,p.net_version) IS NOT TRUE THEN RETURN jsonb_build_object(''unavailable'',''CALCULATED_NET_SOURCE_CHANGED'');END IF; IF EXISTS(SELECT 1 FROM public.payrun_net_revisions net JOIN public.payroll_tax_period_revisions calendar ON calendar.academy_id=net.academy_id AND calendar.period_id=(net.source_snapshot#>>''{calculation,periodId}'')::uuid AND calendar.version=(net.source_snapshot#>>''{calculation,periodVersion}'')::integer WHERE net.academy_id=p.academy_id AND net.run_id=p.run_id AND net.version=p.net_version AND((i->>''paidAt'')::timestamptz AT TIME ZONE(calendar.definition->>''timeZone''))::date IS DISTINCT FROM(calendar.definition->>''payOn'')::date) THEN RETURN jsonb_build_object(''unavailable'',''CALCULATED_NET_PAYMENT_DATE_REVIEW_REQUIRED'');END IF;'||needle);
END $$;
REVOKE ALL ON FUNCTION public.calculated_net_request_valid(jsonb),public.calculated_net_source(uuid,jsonb),public.calculated_net_basis(uuid,integer,jsonb),public.calculated_net_current(uuid,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calculated_net_request_valid(jsonb),public.calculated_net_source(uuid,jsonb),public.calculated_net_basis(uuid,integer,jsonb),public.calculated_net_current(uuid,integer) TO kavosh_runtime;
-- One dynamic binding covers complete YTD history without 500 per-payment
-- binding entries. This predicate reuses the settlement report's whole-source
-- authority,including original hourly sources and every funding/method account.
CREATE FUNCTION public.calculated_net_history_allows(p_run uuid,p_request jsonb,p_scopes jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE current_run record;d jsonb;ids uuid[];n integer;BEGIN
 IF public.calculated_net_request_valid(p_request) IS NOT TRUE THEN RETURN false;END IF;
 SELECT * INTO current_run FROM public.payrun_groups WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_run;IF NOT FOUND THEN RETURN false;END IF;
 SELECT r.definition INTO d FROM public.payroll_tax_period_revisions r WHERE r.academy_id=current_run.academy_id AND r.period_id=(p_request->>'periodId')::uuid AND r.version=(p_request->>'expectedPeriodVersion')::integer;IF d IS NULL THEN RETURN false;END IF;
 SELECT array_agg(id),count(*) INTO ids,n FROM(SELECT pay.id FROM public.payrun_payments pay JOIN public.payrun_net_postings p ON p.academy_id=pay.academy_id AND p.id=pay.posting_id JOIN public.payrun_groups old ON old.academy_id=p.academy_id AND old.id=p.run_id WHERE old.academy_id=current_run.academy_id AND old.id<>current_run.id AND old.person_id=current_run.person_id AND jsonb_array_length(old.source_snapshot->'contexts')=1 AND old.source_snapshot#>>'{contexts,0,employerId}'=current_run.source_snapshot#>>'{contexts,0,employerId}' AND old.source_snapshot#>>'{contexts,0,countryCode}'='CA' AND old.source_snapshot#>>'{contexts,0,classification}'='employee' AND((pay.input->>'paidAt')::timestamptz AT TIME ZONE(d->>'timeZone'))::date BETWEEN DATE '2026-01-01' AND current_run.planned_pay_on ORDER BY pay.id LIMIT 501)x;
 IF n>500 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['financial-reports.view','payruns.view','payrun-net.view','payrun-postings.view','payrun-payments.view','work-pay.view','accounts.view','journals.view','payment-methods.view']) c WHERE public.approval_scope_nonempty(p_scopes->c) IS NOT TRUE) THEN RETURN false;END IF;
 RETURN NOT EXISTS(SELECT 1 FROM public.payrun_payments pay JOIN public.payrun_net_postings p ON p.academy_id=pay.academy_id AND p.id=pay.posting_id JOIN public.payrun_groups g ON g.academy_id=p.academy_id AND g.id=p.run_id WHERE pay.id=ANY(ids) AND NOT(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(jsonb_build_array(p_scopes->'financial-reports.view',p_scopes->'payruns.view',p_scopes->'payrun-net.view',p_scopes->'payrun-postings.view',p_scopes->'payrun-payments.view','{"all":true,"hubs":[]}'::jsonb)) s WHERE public.scope_contains(s,g.scope) IS NOT TRUE)
 AND public.payrun_net_source_allows(g.id,'work-pay.view',p_scopes->'work-pay.view') AND public.payrun_net_source_allows(g.id,'work-pay.view','{"all":true,"hubs":[]}'::jsonb)
 AND(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.source_snapshot->'items') i WHERE i->>'kind'<>'manual_bonus') OR public.payrun_net_source_allows(g.id,'payroll-accruals.view',p_scopes->'payroll-accruals.view'))
 AND(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.source_snapshot->'items') i WHERE i->>'kind'='manual_bonus') OR public.payrun_net_source_allows(g.id,'payroll-adjustments.view',p_scopes->'payroll-adjustments.view'))
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.plan->'accounts') a LEFT JOIN public.finance_accounts f ON f.academy_id=p.academy_id AND f.id=(a->>'id')::uuid CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(p_scopes->'accounts.view',p_scopes->'journals.view','{"all":true,"hubs":[]}'::jsonb)) s WHERE f.id IS NULL OR public.scope_contains(s,CASE WHEN f.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(f.hub_id)) END) IS NOT TRUE) AND public.payrun_net_source_allows(g.id,'work-pay.view',p_scopes->'financial-reports.view')
 AND NOT EXISTS(SELECT 1 FROM public.payrun_payments pay LEFT JOIN public.finance_accounts f ON f.academy_id=pay.academy_id AND f.id=pay.funding_account LEFT JOIN public.finance_payment_methods m ON m.academy_id=pay.academy_id AND m.id=pay.method_id WHERE pay.posting_id=p.id AND(f.id IS NULL OR m.id IS NULL OR public.scope_contains(p_scopes->'accounts.view',CASE WHEN f.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(f.hub_id)) END) IS NOT TRUE OR public.scope_contains(p_scopes->'journals.view',CASE WHEN f.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(f.hub_id)) END) IS NOT TRUE OR public.scope_contains('{"all":true,"hubs":[]}'::jsonb,CASE WHEN f.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(f.hub_id)) END) IS NOT TRUE OR public.scope_contains(p_scopes->'payment-methods.view',CASE WHEN m.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(m.hub_id)) END) IS NOT TRUE OR public.scope_contains('{"all":true,"hubs":[]}'::jsonb,CASE WHEN m.hub_id IS NULL THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(m.hub_id)) END) IS NOT TRUE))));
END $$;
CREATE FUNCTION public.calculated_net_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE who uuid;s jsonb;BEGIN
 SELECT person_id INTO who FROM public.payrun_groups WHERE academy_id=NEW.academy_id AND id=NEW.target_id;IF who IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||'[{"unresolved":true}]'::jsonb;RETURN NEW;END IF;
 s=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',who,'hubId',NULL)),'workContext',jsonb_build_object('personId',who,'hubId',NULL));
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','tax-periods.view','scope',s),jsonb_build_object('capability','payroll-tax.view','scope',s),jsonb_build_object('capability','financial-reports.view','calculatedNetSource',NEW.target_id,'calculationRequest',NEW.payload->'calculationRequest'));RETURN NEW;
END $$;
CREATE TRIGGER zz_calculated_net_base_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='work.payrun-net.calculate') EXECUTE FUNCTION public.payrun_net_privacy();
CREATE TRIGGER zzz_calculated_net_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='work.payrun-net.calculate') EXECUTE FUNCTION public.calculated_net_privacy();
DO $$ DECLARE body text;needle text:='  ELSIF b ? ''personId'' THEN';BEGIN
 SELECT pg_get_functiondef('public.approval_bindings_allow(jsonb,jsonb)'::regprocedure) INTO body;IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'CALCULATED_NET_BINDING_PATCH_CHANGED';END IF;
 EXECUTE replace(body,needle,'  ELSIF b ? ''calculatedNetSource'' THEN
   IF public.calculated_net_history_allows((b->>''calculatedNetSource'')::uuid,b->''calculationRequest'',p_scopes) IS NOT TRUE THEN RETURN false;END IF;
'||needle);
END $$;
REVOKE ALL ON FUNCTION public.calculated_net_history_allows(uuid,jsonb,jsonb),public.calculated_net_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.calculated_net_history_allows(uuid,jsonb,jsonb) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 174 $$;
